var n=`0463-k-s-r`;var t=`world-0463`;var o=`TR`;var r=`western-asia`;var a=4;var l=53;var s={en:`Kısır`,ua:`Кисир`};var m={en:`A traditional dish from Türkiye, centered on bulgur, yellow onion, tomato paste, parsley. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Туреччина. Основні складники: булгур, жовта цибуля, томатна паста, петрушка. Домашній варіант із кількостями продуктів за етапами приготування.`};var g=[{en:`Cook the listed ingredients in simmering water for about 14 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 14 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:14,i:[[`bulgur`,260,`g`],[`water`,380,`ml`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 8 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 8 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:8,i:[[`yellow-onion`,150,`g`],[`extra-virgin-olive-oil`,60,`ml`],[`tomato-paste`,70,`g`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:6,i:[[`parsley`,70,`g`],[`green-onion`,70,`g`],[`mint`,25,`g`],[`lemon-juice`,55,`ml`],[`pomegranate-molasses`,35,`ml`]]},{en:`Cool the prepared ingredients promptly, then refrigerate for about 25 minutes until properly chilled.`,ua:`Швидко охолодіть підготовлені складники, потім поставте в холодильник приблизно на 25 хвилин.`,t:[`rapid-chilling`],m:25,i:[]}];var u={slug:n,id:t,country:`TR`,region:r,servings:4,minutes:53,title:s,text:m,steps:g};export{o as country,u as default,t as id,l as minutes,r as region,a as servings,n as slug,g as steps,m as text,s as title};